const e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Automatisiere deinen Drucker mit sicheren WENN-DANN-Regeln. Standardmäßig aus; aktiviere jede Regel selbst."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Noch keine Regeln. Füge unten eine hinzu und aktiviere sie, wenn du bereit bist."}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"Regel-Engine ist AN"}},off:{t:0,b:{t:2,i:[{t:3}],s:"Regel-Engine ist AUS"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"Einschalten"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"Ausschalten"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"Es läuft nichts, solange nicht sowohl die Engine als auch die einzelne Regel aktiviert sind."}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"Wenn ein Druck abgeschlossen ist"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"Wenn der Drucker einen Fehler meldet"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"Wenn ein Heizer steigt über"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"Wenn ein Heizer fällt unter"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"Eine Benachrichtigung protokollieren"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"Einen G-code-Befehl ausführen"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"Aktiviert"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"Deaktiviert"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"Bearbeiten"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"Löschen"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"Regel löschen"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"Regelname"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"z. B. Heizer nach dem Druck aus"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"Wenn (Auslöser)"}},action:{t:0,b:{t:2,i:[{t:3}],s:"Dann (Aktion)"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"Heizer"}},value:{t:0,b:{t:2,i:[{t:3}],s:"Temperatur (°C)"}},message:{t:0,b:{t:2,i:[{t:3}],s:"Nachricht"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"Wird im Regelprotokoll angezeigt"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"z. B. TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"Regel speichern"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Abbrechen"}},add:{t:0,b:{t:2,i:[{t:3}],s:"Eine Regel hinzufügen"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"Letzte Aktivität"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"benachrichtigt"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"G-code ausgeführt"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"übersprungen (Drucker beschäftigt)"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Fehler"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Anleitung"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Anleitung zur Regel-Engine"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Schließen"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Was ist die Regel-Engine?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Sie überwacht den Drucker und führt eine Aktion aus, wenn eine von dir gesetzte Bedingung erfüllt ist - zum Beispiel eine Notiz protokollieren, wenn ein Druck abgeschlossen ist, oder die Heizer ausschalten. Jede Regel lautet WENN (ein Auslöser) DANN (eine Aktion)."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"Wie sie sicher bleibt"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Die Engine ist standardmäßig aus und jede Regel muss einzeln aktiviert werden, sodass nichts überraschend abläuft. Eine Regel wird einmal ausgelöst, sobald ihre Bedingung zum ersten Mal erfüllt ist. G-code-Aktionen laufen nur, während der Drucker im Leerlauf ist - während eines Drucks werden sie abgelehnt - und jedes Ergebnis wird protokolliert."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossar"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"Auslöser"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Die Bedingung, die eine Regel startet, z. B. ein abgeschlossener Druck oder ein Heizer, der eine Temperatur überschreitet."}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"Aktion"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Was die Regel tut, wenn sie ausgelöst wird: eine Benachrichtigung protokollieren oder einen G-code-Befehl ausführen (nur im Leerlauf)."}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"Aktiviert"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Eine Regel, die eingeschaltet ist. Deaktivierte Regeln bleiben erhalten, werden aber nie ausgelöst."}}}}}}};export{e as default};
